/* $NetBSD: optee.c,v 1.1 2026/10/29 dev Exp $ */

#include <sys/cdefs.h>
__KERNEL_RCSID(0, "$NetBSD: optee.c,v 1.1 2026/10/29 dev Exp $");

#include <sys/param.h>
#include <sys/conf.h>
#include <sys/device.h>
#include <sys/kmem.h>
#include <sys/mutex.h>
#include <sys/systm.h>
#include <arm/arm/smccc.h>
#include <dev/fdt/fdtvar.h>
#include <dev/optee/optee.h>
#include <dev/optee/optee_ioc.h>

#define OPTEE_SMC_FAST_API(fn)	(0xBF000000 | (fn))
#define OPTEE_SMC_FAST_OS(fn)	(0xB2000000 | (fn))

#define OPTEE_SMC_CALLS_COUNT		OPTEE_SMC_FAST_API(0xFF00)
#define OPTEE_SMC_CALLS_UID		OPTEE_SMC_FAST_API(0xFF01)
#define OPTEE_SMC_CALLS_REVISION	OPTEE_SMC_FAST_API(0xFF03)
#define OPTEE_SMC_GET_OS_UUID		OPTEE_SMC_FAST_OS(0x0000)
#define OPTEE_SMC_GET_OS_REVISION	OPTEE_SMC_FAST_OS(0x0001)
#define OPTEE_SMC_EXCHANGE_CAPABILITIES	OPTEE_SMC_FAST_OS(0x0009)

static const struct device_compatible_entry compat_data[] = {
	{ .compat = "linaro,optee-tz" },
	DEVICE_COMPAT_EOL
};

static dev_type_open(optee_open);
static dev_type_close(optee_close);
static dev_type_ioctl(optee_ioctl);

const struct cdevsw optee_cdevsw = {
	.d_open = optee_open,
	.d_close = optee_close,
	.d_read = noread,
	.d_write = nowrite,
	.d_ioctl = optee_ioctl,
	.d_stop = nostop,
	.d_tty = notty,
	.d_poll = nopoll,
	.d_mmap = nommap,
	.d_kqfilter = nokqfilter,
	.d_discard = nodiscard,
	.d_flag = D_OTHER
};

static int opteematch(device_t, cfdata_t, void *);
static void opteeattach(device_t, device_t, void *);
static int opteedetach(device_t, int);

CFATTACH_DECL_NEW(optee, sizeof(struct optee_softc),
    opteematch, opteeattach, opteedetach, NULL);

static int optee_major = -1;
static struct optee_softc *optee_sc = NULL;

static int
opteematch(device_t parent, cfdata_t cf, void *aux)
{
	const struct fdt_attach_args *faa = aux;

	if (!of_compatible_match(faa->faa_phandle, compat_data))
		return 0;
	if (!of_hasprop(faa->faa_phandle, "method"))
		return 0;
	return 1;
}

static void
optee_print_uid(uint32_t a0, uint32_t a1, uint32_t a2, uint32_t a3)
{
	printf(" %08x-%04x-%04x-%04x-%04x%08x",
	    a0,
	    (a1 >> 16) & 0xffff,
	    a1 & 0xffff,
	    (a2 >> 16) & 0xffff,
	    a2 & 0xffff,
	    a3);
	printf(" (raw: %08x %08x %08x %08x)",
	    a0, a1, a2, a3);
}

static void
opteeattach(device_t parent, device_t self, void *aux)
{
	struct optee_softc *sc = device_private(self);
	uint32_t count;
	register_t a0, a1, a2, a3;
	int error;

	sc->sc_dev = self;
	sc->sc_present = false;
	mutex_init(&sc->sc_lock, MUTEX_DEFAULT, IPL_NONE);

	aprint_naive(": OP-TEE Trusted Execution Environment\n");
	aprint_normal(": probing OP-TEE via SMCCC...\n");

	if (!smccc_probe()) {
		aprint_error_dev(self, "SMCCC not available (no PSCI?)\n");
		return;
	}

	DELAY(100000);

	/* Step 1: CALLS_COUNT */
	a0 = OPTEE_SMC_CALLS_COUNT;
	error = smccc_call(a0, 0, 0, 0, 0, &a0, &a1, &a2, &a3);
	if (error) {
		aprint_error_dev(self, "CALLS_COUNT failed: %d\n", error);
		return;
	}
	count = (uint32_t)a0;
	aprint_normal_dev(self, "call count = %u\n", count);
	if (count == 0) {
		aprint_error_dev(self, "OP-TEE not detected\n");
		return;
	}

	/* Step 2: CALLS_UID */
	a0 = OPTEE_SMC_CALLS_UID;
	error = smccc_call(a0, 0, 0, 0, 0, &a0, &a1, &a2, &a3);
	if (error || a0 == 0) {
		aprint_error_dev(self, "OP-TEE not available\n");
		return;
	}
	aprint_normal_dev(self, "API UID:");
	optee_print_uid((uint32_t)a0, (uint32_t)a1,
	    (uint32_t)a2, (uint32_t)a3);
	aprint_normal("\n");

	/* Step 3: CALLS_REVISION */
	a0 = OPTEE_SMC_CALLS_REVISION;
	error = smccc_call(a0, 0, 0, 0, 0, &a0, &a1, &a2, &a3);
	if (error) {
		aprint_error_dev(self, "CALLS_REVISION failed\n");
		return;
	}
	sc->sc_version_major = (uint32_t)a0;
	sc->sc_version_minor = (uint32_t)a1;
	aprint_normal_dev(self, "API revision %u.%u\n",
	    sc->sc_version_major, sc->sc_version_minor);

	/* Step 4: GET_OS_UUID */
	a0 = OPTEE_SMC_GET_OS_UUID;
	error = smccc_call(a0, 0, 0, 0, 0, &a0, &a1, &a2, &a3);
	if (!error && a0 != 0) {
		aprint_normal_dev(self, "OS UUID:");
		optee_print_uid((uint32_t)a0, (uint32_t)a1,
		    (uint32_t)a2, (uint32_t)a3);
		aprint_normal("\n");
	}

	/* Step 5: GET_OS_REVISION */
	a0 = OPTEE_SMC_GET_OS_REVISION;
	error = smccc_call(a0, 0, 0, 0, 0, &a0, &a1, &a2, &a3);
	if (!error) {
		sc->sc_os_rev_major = (uint32_t)a0;
		sc->sc_os_rev_minor = (uint32_t)a1;
		sc->sc_os_rev_build = (uint32_t)a2;
		aprint_normal_dev(self, "OS revision %lu.%lu (build %lu)\n",
		    (u_long)sc->sc_os_rev_major,
		    (u_long)sc->sc_os_rev_minor,
		    (u_long)sc->sc_os_rev_build);
	}

	/* Self-test: re-read revision */
	a0 = OPTEE_SMC_CALLS_REVISION;
	error = smccc_call(a0, 0, 0, 0, 0, &a0, &a1, &a2, &a3);
	if (error == 0 && (uint32_t)a0 == sc->sc_version_major &&
	    (uint32_t)a1 == sc->sc_version_minor &&
	    sc->sc_version_major == 1)
		aprint_normal_dev(self,
		    "self-test: SMC round-trip PASS (ABI v%u.%u)\n",
		    (uint32_t)a0, (uint32_t)a1);
	else
		aprint_error_dev(self,
		    "self-test: SMC round-trip FAIL (err=%d, maj=%u)\n",
		    error, (uint32_t)a0);

	sc->sc_present = true;
	optee_sc = sc;
	error = devsw_attach("optee", NULL, NULL,
	    &optee_cdevsw, &optee_major);
	if (error) {
		aprint_error_dev(self, "devsw_attach failed: %d\n", error);
		sc->sc_present = false;
	} else {
		aprint_normal_dev(self, "/dev/optee registered (major=%d)\n",
		    optee_major);
	}
	aprint_normal_dev(self, "OP-TEE is present and initialized\n");
}

static int
opteedetach(device_t self, int flags)
{
	struct optee_softc *sc = device_private(self);

	if (sc->sc_present && optee_major != -1) {
		devsw_detach(NULL, &optee_cdevsw);
		optee_major = -1;
		optee_sc = NULL;
	}
	mutex_destroy(&sc->sc_lock);
	return 0;
}

static int
optee_open(dev_t dev, int flag, int mode, struct lwp *l)
{
	if (optee_sc == NULL || !optee_sc->sc_present)
		return ENXIO;
	return 0;
}

static int
optee_close(dev_t dev, int flag, int mode, struct lwp *l)
{
	return 0;
}

static int
optee_ioctl(dev_t dev, u_long cmd, void *data, int flag, struct lwp *l)
{
	struct optee_version_arg *va;

	if (optee_sc == NULL || !optee_sc->sc_present)
		return ENXIO;

	switch (cmd) {
	case OPTEE_IOC_GET_VERSION:
		va = (struct optee_version_arg *)data;
		va->major = optee_sc->sc_version_major;
		va->minor = optee_sc->sc_version_minor;
		return 0;
	default:
		return ENOTTY;
	}
}
